<style>.register-kpi{padding:26px 28px;border:1px solid #e8ebf1!important;border-radius:20px;min-height:230px}.register-kpi-top,.register-kpi-main{display:flex;align-items:center;justify-content:space-between}.register-kpi-icon{display:grid;place-items:center;width:54px;height:54px;border-radius:15px;background:color-mix(in srgb,var(--kpi) 12%,#fff);color:var(--kpi);font-size:27px}.register-kpi-top strong,.register-kpi-value{color:var(--kpi)}.register-kpi-main{margin-top:22px;gap:18px}.register-kpi-label{font-weight:700;color:#526078}.register-kpi-value{font-size:34px;font-weight:800}.register-kpi small{color:#95a0b5}.register-gauge{display:grid;place-items:center;width:112px;height:112px;border-radius:50%;background:conic-gradient(var(--kpi) var(--progress),#e9edf5 0);position:relative}.register-gauge:before{content:'';position:absolute;inset:13px;border-radius:50%;background:#fff}.register-gauge span{position:relative;color:var(--kpi);font-size:22px;font-weight:800}.register-filter{border-bottom:1px solid #e5eadf;background:#fbfdf9}.register-modal{display:none;position:fixed;inset:0;z-index:2147483646;background:#0f172aa8;padding:20px;overflow:auto}.register-modal:target{display:flex;align-items:center;justify-content:center}.register-modal .modal-dialog{width:min(760px,calc(100vw - 32px));margin:auto}.register-modal .modal-content{border:2px solid #1f8a70;border-radius:22px;overflow:hidden;background:#fff}.register-modal .modal-header,.register-modal .modal-footer{padding:20px 28px}.register-modal .modal-body{padding:26px 28px;max-height:68vh;overflow:auto}.detail-grid small,.detail-grid strong{display:block}.detail-grid small{text-transform:uppercase;letter-spacing:.05em;font-weight:700;color:#98a2b3;margin-bottom:5px}.detail-grid strong{font-size:17px;color:#172033}.customer-actions{display:inline-flex}.customer-popover-menu:popover-open{position:fixed;inset:auto;margin:0;border:2px solid #10b981;border-radius:16px;padding:7px;box-shadow:0 16px 36px #0f172a35;list-style:none;background:#fff;min-width:210px;z-index:2147483647}.customer-popover-menu .dropdown-item{display:block;border:0;border-radius:8px;background:transparent;width:100%;text-align:left;padding:9px 11px;text-decoration:none}.customer-popover-menu .dropdown-item:hover{background:#ecfdf5}</style>
<script>document.addEventListener('click',function(e){const action=e.target.closest('.customer-popover-menu a[href^="#"]');if(action){action.closest('[popover]')?.hidePopover();return}const b=e.target.closest('[popovertarget^="collateral-actions-"]');if(!b)return;const m=document.getElementById(b.getAttribute('popovertarget'));const r=b.getBoundingClientRect();m.style.top=Math.max(12,Math.min(r.bottom+8,window.innerHeight-230))+'px';m.style.left=Math.max(12,Math.min(r.right-220,window.innerWidth-232))+'px';},true);</script>
