<script>document.querySelectorAll('.register-modal').forEach(function(overlay){overlay.classList.remove('modal','fade');overlay.removeAttribute('aria-hidden');overlay.removeAttribute('tabindex');overlay.addEventListener('click',function(event){if(event.target===overlay){location.hash='register-top';}});});document.addEventListener('keydown',function(event){if(event.key==='Escape'&&document.querySelector('.register-modal:target')){location.hash='register-top';}});document.querySelectorAll('.register-money-input').forEach(function(input){const format=function(){const clean=input.value.replace(/[^0-9.]/g,'');const parts=clean.split('.');input.value=(parts.shift()||'').replace(/\B(?=(\d{3})+(?!\d))/g,',')+(parts.length?'.'+parts.join('').slice(0,2):'');};format();input.addEventListener('input',format);input.form?.addEventListener('submit',function(){input.value=input.value.replace(/,/g,'');});});</script>
